-- Retire produk contoh lama (prefix OL-) agar diganti master dari Excel
UPDATE public.products SET is_active=false WHERE kode_internal LIKE 'OL-%';

-- ── PRODUCTS (upsert by kode_internal = Kode Material) ──

-- ── PRODUCT_ITEMS (analit) — 682 item ──

-- tandai panel (>1 analit)
UPDATE public.products p SET is_panel=true WHERE (SELECT count(*) FROM public.product_items pi WHERE pi.product_id=p.id AND pi.is_active)>1;

-- ── REF_RANGES — 1774 baris ──

